BODY = "\nDIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))\n\n\ndef _connected(mask):\n    pts = np.argwhere(mask)\n    if len(pts) == 0:\n        return False\n    H, W = mask.shape\n    seen = np.zeros(mask.shape, dtype=bool)\n    sy, sx = int(pts[0][0]), int(pts[0][1])\n    seen[sy, sx] = True\n    q = deque([(sy, sx)])\n    n = 1\n    while q:\n        y, x = q.popleft()\n        for dy, dx in DIRS:\n            ny, nx = y + dy, x + dx\n            if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not seen[ny, nx]:\n                seen[ny, nx] = True\n                n += 1\n                q.append((ny, nx))\n    return n == len(pts)\n\n\ndef _clean(H, W, box, corner, tv, th):\n    # Clean L in visible coordinates: a full-height vertical arm (tv columns)\n    # and a full-width horizontal arm (th rows) meeting at one bbox corner.\n    r0, r1, c0, c1 = box\n    C = np.zeros((H, W), dtype=bool)\n    if corner in (0, 2):\n        C[r0:r1 + 1, c0:c0 + tv] = True\n    else:\n        C[r0:r1 + 1, c1 - tv + 1:c1 + 1] = True\n    if corner in (0, 1):\n        C[r0:r0 + th, c0:c1 + 1] = True\n    else:\n        C[r1 - th + 1:r1 + 1, c0:c1 + 1] = True\n    return C\n\n\ndef _explain(g, fgm, C, bg, fg):\n    H, W = C.shape\n\n    def inC(y, x):\n        return 0 <= y < H and 0 <= x < W and bool(C[y, x])\n\n    defects = []\n    rows = set()\n    cols = set()\n    for p in np.argwhere(C != fgm):\n        y, x = int(p[0]), int(p[1])\n        if C[y, x]:\n            # notch: an edge cell of the clean L with exactly one outside side\n            outs = [d for d in DIRS if not inC(y + d[0], x + d[1])]\n            if len(outs) != 1:\n                return None\n            d = (-outs[0][0], -outs[0][1])\n            bump = False\n        else:\n            # bump: an outside cell touching the clean L on exactly one side\n            ins = [d for d in DIRS if inC(y + d[0], x + d[1])]\n            if len(ins) != 1:\n                return None\n            d = ins[0]\n            bump = True\n        if d[0] != 0:\n            if x in cols:\n                return None\n            cols.add(x)\n        else:\n            if y in rows:\n                return None\n            rows.add(y)\n        defects.append((y, x, d, bump))\n    cells = set((y, x) for y, x, _, _ in defects)\n    out = g.copy()\n    edits = {}\n    for y, x, (dy, dx), bump in defects:\n        if bump:\n            cy, cx = y + dy, x + dx\n        else:\n            cy, cx = y, x\n        while inC(cy + dy, cx + dx):\n            cy += dy\n            cx += dx\n        if not bump:\n            cy += dy\n            cx += dx\n        if not (0 <= cy < H and 0 <= cx < W) or (cy, cx) in cells:\n            return None\n        value = bg if bump else fg\n        if (cy,cx) in edits and edits[cy,cx] != value: return None\n        edits[cy,cx] = value\n        out[cy, cx] = value\n    if not _connected(out == fg) or not _connected(out != fg):\n        return None\n    return len(defects), out\n\n\ndef _search(g, bg, fg, boxes, tmin, tmax):\n    H, W = g.shape\n    fgm = g == fg\n    outputs = set()\n    done = set()\n    for box in boxes:\n        if box in done:\n            continue\n        done.add(box)\n        r0, r1, c0, c1 = box\n        if r0 < 0 or c0 < 0 or r1 >= H or c1 >= W:\n            continue\n        hs = r1 - r0 + 1\n        ws = c1 - c0 + 1\n        if hs < 2 or ws < 2:\n            continue\n        for corner in range(4):\n            for tv in range(tmin, min(tmax, ws - 1) + 1):\n                for th in range(tmin, min(tmax, hs - 1) + 1):\n                    res = _explain(g, fgm, _clean(H, W, box, corner, tv, th), bg, fg)\n                    if res is not None:\n                        outputs.add(tuple(map(tuple,res[1].tolist())))\n    return outputs\n\n\ndef solve(demonstrations, grid):\n    g = np.array(grid,dtype=int)\n    if any(int(v) not in (BG,FG) for v in np.unique(g)):\n        raise ValueError('Unexpected L-shape colours')\n    h,w = g.shape\n    outputs = _search(g,BG,FG,[(2,h-3,2,w-3)],3,6)\n    if len(outputs)!=1:\n        raise ValueError('No unique L-shape defect output')\n    return [list(row) for row in next(iter(outputs))]\n"

def build_program(d4,palette):
    return "import numpy as np\nfrom collections import deque\nBG = "+str(int(palette[8]))+"\nFG = "+str(int(palette[1]))+"\n"+BODY
